package io.github.jawedyari87_hue.chalkside;

import android.content.Context;
import android.content.SharedPreferences;
import android.net.Uri;

import java.util.Locale;

/** Shared settings and small helpers. BuildInfo is generated by build.py. */
final class App {
    static final String TAG = "Chalkside";

    private App() {}

    static SharedPreferences prefs(Context c) {
        return c.getSharedPreferences("chalkside", Context.MODE_PRIVATE);
    }

    /** Where the web app lives: the live site, or a dev server for a test build (which may add ?mock). */
    static String base() {
        return BuildInfo.BASE_URL;
    }

    /** The web app with a mode added, e.g. page("overlay") is ...chalkside/?overlay. */
    static String page(String query) {
        String base = base();
        return base + (base.contains("?") ? "&" : "?") + query;
    }

    /** scheme://host[:port], for checking that a page or request is Chalkside's own. */
    static String origin(String url) {
        if (url == null) return "";
        Uri u = Uri.parse(url);
        return (u.getScheme() + "://" + u.getEncodedAuthority()).toLowerCase(Locale.ROOT);
    }

    /** Set by the settings screen when it closes, so the start screen knows whether a key is saved. */
    static boolean hasKey(Context c) {
        // A test build with the fake tutor (?mock) needs no key.
        return prefs(c).getBoolean("hasKey", false) || base().contains("mock");
    }
}
